import { useEffect, useState } from 'react';

// The in-game record board (the coach's club only) beside the league-wide marks: public/data/league/records.json,
// generated by scripts/league_records.py. The Record Book shows it as a "Club" line under each career record and as
// its Season tab.

export interface ClubEntry { value: number; mark: string; player: string; name?: string; pos?: string; team?: string; season?: string; club?: boolean }
export interface ClubRecordRow {
  record: string;
  short: string;
  scope: 'career' | 'season' | 'game' | 'other';
  club: {
    mark: string;
    value: number | null;
    holder: string;
    year: string;
    name?: string;
    team?: string;
    /** From the game's save (record.set): a single game's or play's week (after week 18 a playoff game) and opponent */
    week?: number;
    opponent?: string;
    /** The QB on the field for a play record ("QB B. Crawford") */
    qb?: string;
    /** The exact mark when the save keeps a fraction (2 decimals) */
    exact?: number;
  };
  league: { value: number; mark: string; top: ClubEntry[]; basis: string; clubHolds: boolean } | null;
  broken?: boolean;
}
export interface ClubRecordFile { seasonsFrom: string | null; seasonsTo: string | null; records: ClubRecordRow[] }

let cache: Promise<ClubRecordFile | null> | null = null;
export const loadClubRecords = () =>
  (cache ??= fetch(`${import.meta.env.BASE_URL}data/league/records.json`)
    .then((r) => (r.ok ? (r.json() as Promise<ClubRecordFile>) : null))
    .catch(() => null));

export const useClubRecords = (): ClubRecordFile | null => {
  const [data, setData] = useState<ClubRecordFile | null>(null);
  useEffect(() => {
    let live = true;
    loadClubRecords().then((d) => live && setData(d));
    return () => {
      live = false;
    };
  }, []);
  return data;
};

/** The Record Book's headline career boards and the board record each one matches. */
export const CLUB_RECORD_FOR: Record<string, string> = {
  qbPassYds: 'Best passing career',
  qbPassTD: 'Most TD passes, career',
  rbRushYds: 'Best rushing career',
  wrRecYds: 'Best receiving career',
  wrRecTD: 'Most TD receptions, career',
  defSacks: 'Most sacks, career',
  defINT: 'Most interceptions, career',
};

/** Season records grouped like the career chips (the chip's colour). */
export const SEASON_GROUP = (record: string): 'qb' | 'rb' | 'wr' | 'def' =>
  /passing|TD passes/.test(record) ? 'qb' : /rushing/i.test(record) ? 'rb' : /receiving|TD receptions/.test(record) ? 'wr' : 'def';

/** "QB S. Brandson" -> the full name when known, else the board's own text without the position. */
export const entryName = (e: Pick<ClubEntry, 'name' | 'player'>) => e.name ?? e.player.replace(/^[A-Z]{1,2} /, '').replace(/\s*\(now [^)]+\)/, '');

/** The last regular-season week; later weeks on the board are playoff games. */
export const LAST_REGULAR_WEEK = 18;

/** "Set in week 17 against the Bills" / "Set in a playoff game (week 22) against the Lions", when the board has them. */
export const setInText = (c: ClubRecordRow['club']): string | null => {
  if (c.week == null || !c.opponent) return null;
  const when = c.week > LAST_REGULAR_WEEK ? `a playoff game (week ${c.week})` : `week ${c.week}`;
  return `Set in ${when} against the ${c.opponent}`;
};

/** The player on a play record ("QB S. Brandson → WR D. Haley" -> "D. Haley"), else the holder. */
export const holderName = (c: ClubRecordRow['club']) => c.name ?? entryName({ player: c.holder.split('→').pop()!.trim() });
